#' Extraction of objects generated by \code{\link[sephora]{phenopar_polygon}}
#' 
#' This function allows object extraction contained in the \code{RData}
#' file generated when \code{\link[sephora]{phenopar_polygon}} is called. 
#' 
#' @param      x list (of non-fixed length) containing objects produced through
#'               \code{\link[sephora]{phenopar_polygon}}. This argument is 
#'               needed when \code{file} is not provided.
#' @param   file character giving the name of the file containing the output
#'               of \code{\link[sephora]{phenopar_polygon}}. This argument is
#'               needed when \code{x} is not provided.
#' @param object character vector indicating the object, possibly more than one, 
#'               to be extracted.
#' 
#' @export
#' 
#' @details Valid \code{object}s are: \code{c("x", "freq", "sigma",
#' "m_aug_smooth", "clustering", "clusterSize", "fpca", "fpca_harmfit_params",
#' "fpca_fun_0der", "fpca_fun_1der", "fpca_fun_2der", "fpca_fun_3der", 
#' "fpca_fun_4der", "phenoparams","status")}.
#' 
#' @return Depending on the value of \code{object} the output is:
#' \tabular{ll}{
#'   \code{object}\tab \code{D  E  S  C  R  I  P  T  I  O  N}\cr
#'   \code{------}\tab \code{-------------------------------}\cr
#'   \code{freq}\tab a vector of length equal to \code{length(x)}\cr
#'   \code{clusterSize}\tab a vector of length equal to \code{length(x)}\cr
#'   \code{status}\tab a vector of length equal to \code{length(x)}\cr
#'   \code{x}\tab a matrix with \code{nrow=length(x)}\cr
#'   \code{sigma}\tab a matrix with \code{nrow=length(x)}\cr
#'   \code{fpca}\tab a matrix with \code{nrow=length(x)}\cr
#'   \code{phenoparams}\tab a matrix with \code{nrow=length(x)} and \code{ncol=6}\cr
#'   \code{x_smooth}\tab a list of length equal to \code{length(x)}\cr
#'   \code{m_aug_smooth}\tab a list of length equal to \code{length(x)}\cr
#'   \code{clustering}\tab a list of length equal to \code{length(x)}\cr
#'   \code{fpca_harmfit_params}\tab a list of length equal to \code{length(x)}\cr
#'   \code{fpca_fun_0der}\tab a list of length equal to \code{length(x)}\cr
#'   \code{fpca_fun_1der}\tab a list of length equal to \code{length(x)}\cr
#'   \code{fpca_fun_2der}\tab a list of length equal to \code{length(x)}\cr
#'   \code{fpca_fun_3der}\tab a list of length equal to \code{length(x)}\cr
#'   \code{fpca_fun_4der}\tab a list of length equal to \code{length(x)}\cr
#' }
#' 
#' @seealso \code{\link[sephora]{phenopar_polygon}}, \code{\link[sephora]{getSpiralPlot}}. 
#' 
extract_sephora <- function(x, file, object){

  if(missing(x)){
    if(missing(file)){
      stop("x or file must be provided")
    } else {
      x <- LoadToEnvironment(file)$output
    }
  } else {
    if(!inherits(x, "list")){
      stop("x must be a list")
    }
  }
  
  if(missing(object)){
    stop("object must be provided")
  }

  switch(object,
         x = return_matrix(list=x, type="x"),
         freq = return_vector(list=x, type="freq"),
         sigma = return_matrix(list=x, type="sigma"),
         x_smooth = return_list(list=x, type="x_smooth"),
         m_aug_smooth = return_list(list=x, type="m_aug_smooth"),
         clustering = return_list(list=x, type="clustering"),
         clusterSize = return_vector(list=x, type="clusterSize"),
         fpca = return_matrix(list=x, type="fpca"),
         fpca_harmfit_params = return_list(x, type="fpca_harmfit_params"),
         fpca_fun_0der = return_list(list=x, type="fpca_fun_0der"),
         fpca_fun_1der = return_list(list=x, type="fpca_fun_1der"),
         fpca_fun_2der = return_list(list=x, type="fpca_fun_2der"),
         fpca_fun_3der = return_list(list=x, type="fpca_fun_3der"),
         fpca_fun_4der = return_list(list=x, type="fpca_fun_4der"),
         phenoparams = return_matrix(list=x, type="phenoparams"),
         status = return_vector(list=x, type="status"))
}

# --- Added on Oct 29, 2026

what_objects <- function(x, whatToExtract){
  
  output <- vector(mode="list", length=length(whatToExtract))
  output <- lapply(whatToExtract, function(s) x[[s]] )
  names(output) <- whatToExtract
  
  output
}


return_matrix <- function(list, type=c("x", "sigma", "fpca", "phenoparams")){
  type <- match.arg(type)
  
  if(type == "x"){
    output <- as.matrix(x=t(sapply(1:length(list), function(s) list[[s]]$x)),
                        nrow=length(list), ncol=length(list[[1]]$x))
  }
  
  if(type == "sigma"){
    output <- as.matrix(x=t(sapply(1:length(list), function(s) list[[s]]$sigma)),
                        nrow=length(list), ncol=length(list[[1]]$sigma))
  }
  
  if(type == "fpca"){
    output <- as.matrix(x=t(sapply(1:length(list), function(s) list[[s]]$fpca)),
                        nrow=length(list), ncol=length(list[[1]]$fpca))
  }
  
  if(type == "phenoparams"){
    output <- matrix(nrow=length(list), ncol=6)
    output[,1] <- getParam(x=list, phenoparam = "GU")
    output[,2] <- getParam(x=list, phenoparam = "SoS")
    output[,3] <- getParam(x=list, phenoparam = "Mat")
    output[,4] <- getParam(x=list, phenoparam = "Sen")
    output[,5] <- getParam(x=list, phenoparam = "EoS")
    output[,6] <- getParam(x=list, phenoparam = "Dor")
    colnames(output) <- c("GU", "SoS", "Mat", "Sen", "EoS", "Dor")
    # output <- as.matrix(x=t(sapply(1:length(list), function(s) list[[s]]$phenoparams)),
    #                     nrow=length(list), ncol=length(list[[1]]$phenoparams))
  }
  
  rownames(output) <- paste0("result.", 1:nrow(output))
  output
}

return_vector <- function(list, type=c("freq", "clusterSize", "status")){
  type <- match.arg(type)
  
  if(type == "freq"){
    output <- rep(list[[1]]$freq, length(list))
  }
  
  if(type == "clusterSize"){
    output <- rep(list[[1]]$clusterSize, length(list))
  }
  
  if(type == "status"){
    output <- sapply(1:length(list), function(s) list[[s]]$status)
  }
  
  return(output)
}

return_list <- function(list, type=c("x_smooth", "m_aug_smooth", "clustering",
                                     "fpca_harmfit_params", "fpca_fun_0der",
                                     "fpca_fun_1der", "fpca_fun_2der",
                                     "fpca_fun_3der", "fpca_fun_4der")){
  
  type <- match.arg(type)
  
  if(type == "x_smooth"){
    output <- lapply(1:length(list), function(s) list[[s]]$x_smooth)
  }
  
  if(type == "m_aug_smooth"){
    output <- lapply(1:length(list), function(s) list[[s]]$m_aug_smooth)
  }
  
  if(type == "clustering"){
    output <- lapply(1:length(list), function(s) list[[s]]$clustering)
  }
  
  if(type == "fpca_harmfit_params"){
    output <- lapply(1:length(list), function(s) list[[s]]$fpca_harmfit_params)
  }
  
  if(type == "fpca_fun_0der"){
    output <- lapply(1:length(list), function(s) list[[s]]$fpca_fun_0der)
  }
  
  if(type == "fpca_fun_1der"){
    output <- lapply(1:length(list), function(s) list[[s]]$fpca_fun_1der)
  }
  
  if(type == "fpca_fun_2der"){
    output <- lapply(1:length(list), function(s) list[[s]]$fpca_fun_2der)
  }
  
  if(type == "fpca_fun_3der"){
    output <- lapply(1:length(list), function(s) list[[s]]$fpca_fun_3der)
  }
  
  if(type == "fpca_fun_4der"){
    output <- lapply(1:length(list), function(s) list[[s]]$fpca_fun_4der)
  }
  
  return(output)  
}

# --- Added on Feb 9, 2024
# --- auxiliary function for return_matrix(,type="phenoparams")

getParam <- function(x, phenoparam){
  sapply(1:length(x), function(s) ifelse(length(as.numeric(x[[s]]$phenoparams[ names(x[[s]]$phenoparams) == phenoparam  ])) !=0,
                                         as.numeric(x[[s]]$phenoparams[ names(x[[s]]$phenoparams) == phenoparam]), NA))
}


